IPAddress local_IP(192,168,68,142);
IPAddress gateway(192,168,68,1);
IPAddress subnet(255,255,255,0);

// =====================================================
// S3 PINOUT
// =====================================================

#define INA226_SDA_PIN       8
#define INA226_SCL_PIN       9
#define BATTERY_VOLTAGE_PIN  4

// =====================================================
// BATTERY / INA226
// =====================================================

#define INA226_ADDRESS 0x40

const float SHUNT_OHMS = 0.00075;
const float INA226_SHUNT_LSB_V = 0.0000025;

const float VOLTAGE_DIVIDER_RATIO = 5.038;
const float VOLTAGE_CALIBRATION   = 1.000;

const float BATTERY_CAPACITY_AH = 80.0;

// CONFIRMED WITH METER:
// + current = DISCHARGING
// - current = CHARGING

const float CURRENT_DEADBAND_A = 0.01;

// =====================================================
// SERVER / STORAGE
// =====================================================

WebServer server(80);
Preferences preferences;

// =====================================================
// LIVE DATA
// =====================================================

float batteryVoltage = 0;
float rawBatteryVoltage = 0;

float shuntVoltage_mV = 0;

float current_A = 0;
float filteredCurrent_A = 0;

float power_W = 0;

float peakDischarge_A = 0;
float peakCharge_A = 0;

// =====================================================
// SOC
// =====================================================

bool socSynchronized = false;

float remainingAh = 0;

// Session counters

float sessionUsedAh = 0;
float sessionChargedAh = 0;

unsigned long sessionStartMillis = 0;

// =====================================================
// TIME TO EMPTY
// =====================================================

// Slow discharge-current average.
// This intentionally reacts much slower than the
// dashboard current so TTE doesn't jump everywhere.

float averageDischarge_A = 0;

const float TTE_ALPHA = 0.005;

// =====================================================
// TIMING
// =====================================================

const unsigned long SAMPLE_INTERVAL_MS = 100;
unsigned long lastSampleMillis = 0;

const unsigned long SAVE_INTERVAL_MS = 60000;
unsigned long lastSaveMillis = 0;

// =====================================================
// INA226
// =====================================================

bool readINA226Register(uint8_t reg, int16_t &value) {

  Wire.beginTransmission(INA226_ADDRESS);
  Wire.write(reg);

  if (Wire.endTransmission(false) != 0)
    return false;

  Wire.requestFrom(INA226_ADDRESS,(uint8_t)2);

  if (Wire.available() < 2)
    return false;

  uint16_t raw =
    ((uint16_t)Wire.read() << 8) |
    Wire.read();

  value = (int16_t)raw;

  return true;
}

bool readShuntVoltage(float &millivolts) {

  int16_t raw;

  if (!readINA226Register(0x01,raw))
    return false;

  millivolts =
    raw *
    INA226_SHUNT_LSB_V *
    1000.0;

  return true;
}

// =====================================================
// VOLTAGE ADC FILTERING
// =====================================================

void sortValues(uint32_t values[],int count) {

  for(int i=0;i<count-1;i++) {

    for(int j=i+1;j<count;j++) {

      if(values[j] < values[i]) {

        uint32_t t=values[i];
        values[i]=values[j];
        values[j]=t;
      }
    }
  }
}

float readBatteryVoltage() {

  const int N=64;

  uint32_t samples[N];

  for(int i=0;i<N;i++) {

    samples[i] =
      analogReadMilliVolts(
        BATTERY_VOLTAGE_PIN
      );

    delayMicroseconds(150);
  }

  sortValues(samples,N);

  uint32_t total=0;
  int count=0;

  // discard lowest/highest 12 samples

  for(int i=12;i<52;i++) {

    total += samples[i];
    count++;
  }

  float sensorV =
    (total/(float)count) /
    1000.0;

  return
    sensorV *
    VOLTAGE_DIVIDER_RATIO *
    VOLTAGE_CALIBRATION;
}

// =====================================================
// PERSISTENT BATTERY STATE
// =====================================================

void saveBatteryState() {

  preferences.begin("battery",false);

  preferences.putBool(
    "synced",
    socSynchronized
  );

  preferences.putFloat(
    "remaining",
    remainingAh
  );

  preferences.end();

  lastSaveMillis=millis();
}

void loadBatteryState() {

  preferences.begin("battery",true);

  socSynchronized =
    preferences.getBool(
      "synced",
      false
    );

  remainingAh =
    preferences.getFloat(
      "remaining",
      0
    );

  preferences.end();

  if(socSynchronized) {

    remainingAh =
      constrain(
        remainingAh,
        0.0,
        BATTERY_CAPACITY_AH
      );
  }
}

// =====================================================
// SET FULL
// =====================================================

void setBatteryFull() {

  socSynchronized=true;

  remainingAh=BATTERY_CAPACITY_AH;

  sessionUsedAh=0;
  sessionChargedAh=0;

  peakDischarge_A=0;
  peakCharge_A=0;

  averageDischarge_A=0;

  sessionStartMillis=millis();

  saveBatteryState();
}

// =====================================================
// SOC
// =====================================================

float getSOC() {

  if(!socSynchronized)
    return 0;

  return
    (remainingAh /
     BATTERY_CAPACITY_AH)
    * 100.0;
}

// =====================================================
// BATTERY STATUS
// =====================================================

String batteryStatus() {

  if(filteredCurrent_A > 0.10)
    return "DISCHARGING";

  if(filteredCurrent_A < -0.10)
    return "CHARGING";

  return "IDLE";
}

// =====================================================
// TIME TO EMPTY
// =====================================================

String timeToEmpty() {

  if(!socSynchronized)
    return "--";

  // Only meaningful while discharging

  if(averageDischarge_A < 0.10)
    return "--";

  float hours =
    remainingAh /
    averageDischarge_A;

  // Prevent ridiculous display values

  if(hours > 999)
    return ">999h";

  int wholeHours =
    (int)hours;

  int minutes =
    (int)(
      (hours-wholeHours)*60
    );

  char buffer[30];

  snprintf(
    buffer,
    sizeof(buffer),
    "%dh %02dm",
    wholeHours,
    minutes
  );

  return String(buffer);
}

// =====================================================
// SESSION RUNTIME
// =====================================================

String formatRuntime() {

  unsigned long sec =
    (millis()-sessionStartMillis)/1000;

  unsigned long hr=sec/3600;
  unsigned long min=(sec%3600)/60;

  sec%=60;

  char buffer[20];

  snprintf(
    buffer,
    sizeof(buffer),
    "%02lu:%02lu:%02lu",
    hr,min,sec
  );

  return String(buffer);
}

// =====================================================
// UPDATE BATTERY
// =====================================================

void updateBatteryMonitor() {

  unsigned long now=millis();

  if(
    now-lastSampleMillis <
    SAMPLE_INTERVAL_MS
  )
    return;

  unsigned long elapsedMs =
    now-lastSampleMillis;

  lastSampleMillis=now;

  // ---------------------------------------------------
  // VOLTAGE
  // ---------------------------------------------------

  rawBatteryVoltage =
    readBatteryVoltage();

  if(batteryVoltage==0) {

    batteryVoltage =
      rawBatteryVoltage;
  }

  else {

    batteryVoltage =
      0.10*rawBatteryVoltage +
      0.90*batteryVoltage;
  }

  // ---------------------------------------------------
  // CURRENT
  // ---------------------------------------------------

  float newShunt;

  if(readShuntVoltage(newShunt)) {

    shuntVoltage_mV =
      newShunt;

    current_A =
      (shuntVoltage_mV/1000.0) /
      SHUNT_OHMS;

    if(
      fabs(current_A) <
      CURRENT_DEADBAND_A
    )
      current_A=0;

    filteredCurrent_A =
      0.25*current_A +
      0.75*filteredCurrent_A;

    // -------------------------------------------------
    // DISCHARGE
    // -------------------------------------------------

    if(current_A > 0) {

      if(current_A > peakDischarge_A)
        peakDischarge_A=current_A;

      // Slow TTE load average

      if(averageDischarge_A==0) {

        averageDischarge_A =
          current_A;
      }

      else {

        averageDischarge_A =
          TTE_ALPHA*current_A +
          (1.0-TTE_ALPHA)*
          averageDischarge_A;
      }
    }

    // -------------------------------------------------
    // CHARGE
    // -------------------------------------------------

    if(current_A < 0) {

      float charge=-current_A;

      if(charge > peakCharge_A)
        peakCharge_A=charge;
    }

    // -------------------------------------------------
    // AH
    // -------------------------------------------------

    float elapsedHours =
      elapsedMs /
      3600000.0;

    float deltaAh =
      current_A *
      elapsedHours;

    if(current_A > 0)
      sessionUsedAh += deltaAh;

    else if(current_A < 0)
      sessionChargedAh += -deltaAh;

    // -------------------------------------------------
    // SOC
    // -------------------------------------------------

    if(socSynchronized) {

      remainingAh -= deltaAh;

      remainingAh =
        constrain(
          remainingAh,
          0.0,
          BATTERY_CAPACITY_AH
        );
    }
  }

  // ---------------------------------------------------
  // POWER
  // ---------------------------------------------------

  power_W =
    batteryVoltage *
    filteredCurrent_A;

  // ---------------------------------------------------
  // SAVE
  // ---------------------------------------------------

  if(
    socSynchronized &&
    now-lastSaveMillis >=
    SAVE_INTERVAL_MS
  ) {

    saveBatteryState();
  }
}

// =====================================================
// RESET SESSION
// =====================================================

void resetSession() {

  sessionUsedAh=0;
  sessionChargedAh=0;

  peakDischarge_A=0;
  peakCharge_A=0;

  averageDischarge_A=0;

  sessionStartMillis=millis();
}

// =====================================================
// RETURN HOME
// =====================================================

void returnHome() {

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303,
    "text/plain",
    ""
  );
}

