// =====================================================
// SERVER
// =====================================================

void setupWebServer(){

  server.on("/",HTTP_GET,[](){

    server.send(
      200,
      "text/html",
      buildPage()
    );
  });

  server.on("/setfull",HTTP_GET,[](){

    setBatteryFull();
    returnHome();
  });

  server.on("/reset",HTTP_GET,[](){

    resetSession();
    returnHome();
  });

  server.on("/updatepage",HTTP_GET,[](){

    server.send(
      200,
      "text/html",
      updatePage
    );
  });

  server.on(
    "/update",
    HTTP_POST,

    [](){

      bool success =
        !Update.hasError();

      server.send(
        success?200:500,
        "text/plain",
        success?
        "UPDATE SUCCESSFUL - REBOOTING":
        "UPDATE FAILED"
      );

      delay(1000);

      if(success)
        ESP.restart();
    },

    [](){

      HTTPUpload& upload =
        server.upload();

      if(
        upload.status ==
        UPLOAD_FILE_START
      ){

        Update.begin(
          UPDATE_SIZE_UNKNOWN
        );
      }

      else if(
        upload.status ==
        UPLOAD_FILE_WRITE
      ){

        Update.write(
          upload.buf,
          upload.currentSize
        );
      }

      else if(
        upload.status ==
        UPLOAD_FILE_END
      ){

        Update.end(true);
      }
    }
  );

  server.begin();
}

// =====================================================
// SETUP
// =====================================================

void setup(){

  Serial.begin(115200);

  pinMode(
    BATTERY_VOLTAGE_PIN,
    INPUT
  );

  analogReadResolution(12);

  Wire.begin(
    INA226_SDA_PIN,
    INA226_SCL_PIN
  );

  loadBatteryState();

  WiFi.mode(WIFI_STA);

  WiFi.config(
    local_IP,
    gateway,
    subnet
  );

  WiFi.begin(
    ssid,
    password
  );

  while(
    WiFi.status()!=
    WL_CONNECTED
  ){

    delay(500);
  }

  sessionStartMillis=millis();
  lastSampleMillis=millis();
  lastSaveMillis=millis();

  setupWebServer();
}

// =====================================================
// LOOP
// =====================================================

void loop(){

  updateBatteryMonitor();

  server.handleClient();
}
